#!/usr/bin/env python3
"""Operational board - server-side storage, no AIS required.
Generated from public/board.html by scripts/build-flask.mjs - edit the HTML, then rebuild.
"""
import json, os, threading
from flask import Flask, jsonify, request, Response
from flask_cors import CORS

lock = threading.Lock()
main_ships = []
archive_ships = []


def load_storage():
    try:
        if os.path.exists("ships.json"):
            with open("ships.json", "r", encoding="utf-8") as f:
                data = json.load(f)
                main_ships[:] = data.get("main", [])
                archive_ships[:] = data.get("archive", [])
    except Exception as e:
        print("Load error:", e)


def save_storage():
    with open("ships.json", "w", encoding="utf-8") as f:
        json.dump({"main": main_ships, "archive": archive_ships}, f, ensure_ascii=False, indent=2)


load_storage()
app = Flask(__name__)
CORS(app)

HTML = r"""<!DOCTYPE html>
<html lang="he" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta name="color-scheme" content="dark">
<meta name="theme-color" content="#060a14">
<title>מסך מבצעי — מעבר גבול ימי</title>
<script>
(function(){try{var t=localStorage.getItem('board-theme');if(t==='light'||t==='sand')document.documentElement.setAttribute('data-theme',t);}catch(_){}})();
</script>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Heebo:wght@400;500;600;700;800;900&family=IBM+Plex+Mono:wght@500;600;700&display=swap" rel="stylesheet">
<style>
:root{
  --bg:#060a14;
  --bg-2:#0a1120;
  --panel:rgba(16,25,45,.78);
  --panel-solid:#0e1729;
  --raised:#15203a;
  --line:rgba(120,150,210,.16);
  --line-strong:rgba(120,150,210,.30);
  --text:#eef3ff;
  --mid:#a9b8d8;
  --low:#7d8fb5;

  --cyan:#22d3ee;
  --blue:#60a5fa;
  --green:#34d399;
  --amber:#fbbf24;
  --red:#fb7185;
  --violet:#a78bfa;

  --glow1:rgba(34,211,238,.14);
  --glow2:rgba(96,165,250,.12);
  --card-top:rgba(24,36,64,.85);
  --input-bg:#0a1325;
  --th-bg:#0c1528;
  --hover:rgba(255,255,255,.025);
  --soft:rgba(255,255,255,.04);
  --btn-a:#2dd4ee;
  --btn-b:#0ea5c6;
  --btn-text:#03111a;
  --backdrop:rgba(2,6,16,.75);
  --grid-op:.25;
  color-scheme:dark;

  --sans:'Heebo',system-ui,sans-serif;
  --mono:'IBM Plex Mono',ui-monospace,monospace;
}
html[data-theme="light"]{
  --bg:#eef2f9;
  --bg-2:#f8faff;
  --panel:rgba(255,255,255,.92);
  --panel-solid:#ffffff;
  --raised:#e7edf8;
  --line:rgba(30,64,130,.14);
  --line-strong:rgba(30,64,130,.28);
  --text:#0f1b33;
  --mid:#3f5075;
  --low:#62749a;

  --cyan:#0e7490;
  --blue:#2563eb;
  --green:#047857;
  --amber:#b45309;
  --red:#be123c;
  --violet:#6d28d9;

  --glow1:rgba(14,116,144,.12);
  --glow2:rgba(37,99,235,.10);
  --card-top:rgba(255,255,255,1);
  --input-bg:#ffffff;
  --th-bg:#e9eff9;
  --hover:rgba(15,40,100,.04);
  --soft:rgba(15,40,100,.05);
  --btn-a:#0e7490;
  --btn-b:#0b5f78;
  --btn-text:#ffffff;
  --backdrop:rgba(20,35,70,.45);
  --grid-op:.5;
  --edge:68%;
  --edge-treat:85%;
  --card-shadow:0 .15rem .9rem rgba(15,40,100,.10);
  color-scheme:light;
}
html[data-theme="sand"]{
  --bg:#f6f1e7;
  --bg-2:#fcf9f2;
  --panel:rgba(255,253,248,.94);
  --panel-solid:#fffdf8;
  --raised:#efe7d6;
  --line:rgba(110,80,30,.16);
  --line-strong:rgba(110,80,30,.30);
  --text:#2a2217;
  --mid:#5c4d36;
  --low:#86775d;

  --cyan:#0f766e;
  --blue:#1d4ed8;
  --green:#15803d;
  --amber:#b45309;
  --red:#b91c1c;
  --violet:#7e22ce;

  --glow1:rgba(15,118,110,.10);
  --glow2:rgba(180,83,9,.09);
  --card-top:rgba(255,255,255,1);
  --input-bg:#ffffff;
  --th-bg:#f0e8d8;
  --hover:rgba(110,80,30,.05);
  --soft:rgba(110,80,30,.06);
  --btn-a:#0f766e;
  --btn-b:#0b5e57;
  --btn-text:#ffffff;
  --backdrop:rgba(42,34,23,.45);
  --grid-op:.5;
  --edge:68%;
  --edge-treat:85%;
  --card-shadow:0 .15rem .9rem rgba(110,80,30,.12);
  color-scheme:light;
}
*{box-sizing:border-box;margin:0;padding:0;}
html{font-size:clamp(13px,.8334vw,44px);}
html,body{height:100%;}
body{
  background:var(--bg);
  color:var(--text);
  font-family:var(--sans);
  overflow:hidden;
  -webkit-font-smoothing:antialiased;
}
body::before{
  content:'';position:fixed;inset:0;z-index:-2;
  background:
    radial-gradient(60rem 36rem at 85% -10%, var(--glow1), transparent 60%),
    radial-gradient(50rem 34rem at -5% 105%, var(--glow2), transparent 60%),
    linear-gradient(180deg,var(--bg-2),var(--bg));
}
body::after{
  content:'';position:fixed;inset:0;z-index:-1;pointer-events:none;
  background:url(data:image/jpeg;base64,) center bottom/cover no-repeat;
  opacity:.7;
}
html[data-theme="light"] body::after{background-image:url(data:image/jpeg;base64,);opacity:.9;}
html[data-theme="sand"] body::after{background-image:url(data:image/jpeg;base64,);opacity:.8;filter:sepia(.55) saturate(.9);}
body.idle.view-display{cursor:none;}

.app{height:100vh;display:flex;flex-direction:column;padding:1.4rem 1.8rem 0;gap:1.1rem;}

/* ---------- Header ---------- */
.header{
  display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:2rem;
}
.brand{display:flex;align-items:center;gap:1rem;}
.brand-mark{
  width:3.6rem;height:3.6rem;border-radius:1rem;display:grid;place-items:center;
  background:linear-gradient(145deg,color-mix(in srgb,var(--cyan) 25%,transparent),color-mix(in srgb,var(--blue) 12%,transparent));
  border:1px solid color-mix(in srgb,var(--cyan) 45%,transparent);
  box-shadow:0 0 2rem color-mix(in srgb,var(--cyan) 25%,transparent), inset 0 0 1.2rem color-mix(in srgb,var(--cyan) 12%,transparent);
  color:var(--cyan);
}
.brand-mark svg{width:2rem;height:2rem;}
.eyebrow{font-size:.9rem;font-weight:600;letter-spacing:.12em;color:var(--cyan);}
.brand h1{font-size:1.9rem;font-weight:800;line-height:1.15;margin-top:.15rem;letter-spacing:-.01em;}

.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.9rem;max-width:62rem;justify-self:center;width:100%;}
.kpi{
  background:var(--panel);border:1px solid var(--line);border-radius:1rem;
  padding:.8rem 1.2rem;display:flex;flex-direction:column;gap:.1rem;
  backdrop-filter:blur(10px);position:relative;overflow:hidden;
}
.kpi::after{content:'';position:absolute;inset-inline:0;top:0;height:.18rem;background:var(--c,var(--cyan));opacity:.85;}
.kpi .n{font-family:var(--mono);font-weight:700;font-size:2.7rem;line-height:1.05;font-variant-numeric:tabular-nums;}
.kpi .l{font-size:1rem;color:var(--mid);font-weight:500;}
.kpi.k-ships{--c:var(--cyan);}
.kpi.k-crew{--c:var(--blue);}
.kpi.k-pax{--c:var(--violet);}
.kpi.k-treat{--c:var(--green);}
.kpi.k-treat.hot{--c:var(--red);border-color:color-mix(in srgb,var(--red) 55%,transparent);background:linear-gradient(180deg,color-mix(in srgb,var(--red) 16%,transparent),var(--panel));}
.kpi.k-treat.hot .n{color:var(--red);}
.kpi.k-treat.hot{animation:glow 2.4s ease-in-out infinite;}
@keyframes glow{0%,100%{box-shadow:0 0 0 transparent;}50%{box-shadow:0 0 2.2rem color-mix(in srgb,var(--red) 35%,transparent);}}

.clock{text-align:end;min-width:13rem;}
.clock .time{font-family:var(--mono);font-weight:600;font-size:3.4rem;line-height:1;letter-spacing:-.02em;font-variant-numeric:tabular-nums;}
.clock .time span{color:var(--cyan);}
.clock .date{font-size:1.1rem;color:var(--mid);margin-top:.4rem;font-weight:500;}

/* ---------- Views ---------- */
.view{display:none;flex:1;min-height:0;}
.view.active{display:flex;flex-direction:column;}
.view-scroll{overflow:auto;padding-bottom:1.2rem;scrollbar-width:thin;scrollbar-color:var(--line-strong) transparent;}

/* ---------- Display (TV) ---------- */
.lanes{flex:1;min-height:0;display:grid;grid-template-columns:1.25fr 1fr;gap:1.4rem;}
.lane{display:flex;flex-direction:column;min-height:0;}
.lane-head{display:flex;align-items:center;gap:.8rem;padding:0 .3rem .8rem;}
.lane-head .ico{width:2.6rem;height:2.6rem;border-radius:.8rem;display:grid;place-items:center;background:color-mix(in srgb,var(--c) 18%,transparent);color:var(--c);border:1px solid color-mix(in srgb,var(--c) 45%,transparent);}
.lane-head .ico svg{width:1.5rem;height:1.5rem;}
.lane-head h2{font-size:1.7rem;font-weight:800;}
.lane-head .count{margin-inline-start:auto;font-family:var(--mono);font-weight:700;font-size:1.5rem;color:var(--c);background:color-mix(in srgb,var(--c) 14%,transparent);padding:.1rem .9rem;border-radius:99px;}
.lane.in{--c:var(--cyan);}
.lane.out{--c:var(--amber);}
.lane-body{flex:1;min-height:0;overflow:hidden;display:flex;flex-direction:column;gap:.65rem;padding-bottom:.3rem;}
.lane-body.overflowing{
  mask-image:linear-gradient(to bottom,#000 calc(100% - 3rem),transparent);
  -webkit-mask-image:linear-gradient(to bottom,#000 calc(100% - 3rem),transparent);
}

.card{
  --c:var(--blue);
  flex:none;position:relative;
  background:linear-gradient(180deg,var(--card-top),var(--panel));
  border:2px solid color-mix(in srgb,var(--c) var(--edge,32%),var(--line-strong));border-radius:1.1rem;
  box-shadow:var(--card-shadow,none);
  padding:.75rem 1.2rem;padding-inline-start:1.6rem;
  display:flex;flex-direction:column;gap:.5rem;overflow:hidden;
}
.card::before{
  content:'';position:absolute;inset-block:0;inset-inline-start:0;width:.45rem;background:var(--c);
  box-shadow:0 0 1.4rem color-mix(in srgb,var(--c) 60%,transparent);
}
.card.s-wait{--c:var(--blue);}
.card.s-ready{--c:var(--amber);}
.card.s-ok{--c:var(--green);}
.card.s-active{--c:var(--violet);}
.card.has-treat{border-color:color-mix(in srgb,var(--red) var(--edge-treat,60%),transparent);}
.card.long-wait{border-color:color-mix(in srgb,var(--red) var(--edge-treat,75%),transparent);}
.pills{flex:none;display:flex;align-items:center;gap:.6rem;}
.pill.alert{--c:var(--red);}
.pill.alert i{animation:blink 1.6s ease-in-out infinite;}
.wait-badge{
  display:inline-flex;align-items:center;gap:.4rem;margin-top:.35rem;padding:.15rem .6rem;border-radius:99px;
  font-size:.85rem;font-weight:700;white-space:nowrap;color:var(--red);
  background:color-mix(in srgb,var(--red) 14%,transparent);border:1px solid color-mix(in srgb,var(--red) 50%,transparent);
}
.wait-badge i{width:.5rem;height:.5rem;border-radius:50%;background:var(--red);}
tr.row-long-wait > td:first-child{box-shadow:inset -.3rem 0 0 var(--red);}

.card-top{display:flex;align-items:center;justify-content:space-between;gap:1rem;}
.ship-name{font-size:1.8rem;font-weight:800;line-height:1.15;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.ship-meta{font-size:1rem;color:var(--mid);margin-top:.2rem;font-weight:500;}
.ship-meta b{color:var(--text);font-weight:600;}
.ship-meta .sep{opacity:.4;margin-inline:.45rem;}

.pill{
  flex:none;display:inline-flex;align-items:center;gap:.6rem;
  padding:.45rem 1.1rem;border-radius:99px;font-weight:700;font-size:1.15rem;white-space:nowrap;
  color:var(--c);background:color-mix(in srgb,var(--c) 15%,transparent);
  border:1px solid color-mix(in srgb,var(--c) 50%,transparent);
}
.pill i{width:.7rem;height:.7rem;border-radius:50%;background:var(--c);box-shadow:0 0 .8rem var(--c);}
.card.s-active .pill i,.card.s-ready .pill i{animation:blink 1.6s ease-in-out infinite;}
@keyframes blink{50%{opacity:.25;}}

.metrics{display:grid;grid-template-columns:1.5fr 1fr .8fr .7fr .8fr .8fr;gap:.6rem;}
.m{display:flex;flex-direction:column;min-width:0;padding-top:.5rem;border-top:1px solid var(--line);}
.m .k{font-size:.9rem;color:var(--low);font-weight:600;letter-spacing:.03em;}
.m .v{font-size:1.6rem;font-weight:700;line-height:1.2;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.m .v.mono{font-family:var(--mono);font-variant-numeric:tabular-nums;}
.m .v.zero{color:var(--low);font-weight:500;}
.m .sub{font-size:.95rem;font-weight:600;color:var(--mid);}
.m .sub.soon{color:var(--amber);}
.m .sub.late{color:var(--red);}
.m.treat .v:not(.zero){color:var(--red);}
.card-notes{font-size:1rem;color:var(--mid);padding:.3rem .8rem;background:var(--soft);border-radius:.6rem;border:1px dashed var(--line-strong);}

.lane-empty{
  flex:1;display:grid;place-items:center;text-align:center;color:var(--low);font-size:1.4rem;font-weight:500;
  border:1px dashed var(--line-strong);border-radius:1.1rem;min-height:12rem;
}

/* ---------- Footer / nav ---------- */
.footer{
  flex:none;display:flex;align-items:center;justify-content:space-between;gap:1rem;
  padding:.7rem 0 1rem;border-top:1px solid var(--line);color:var(--low);font-size:.95rem;
}
.live{display:flex;align-items:center;gap:.6rem;font-weight:500;}
.live i{width:.65rem;height:.65rem;border-radius:50%;background:var(--green);box-shadow:0 0 .8rem var(--green);animation:blink 2s ease-in-out infinite;}
.live.demo i{background:var(--amber);box-shadow:0 0 .8rem var(--amber);}
.live.err i{background:var(--red);box-shadow:0 0 .8rem var(--red);animation:none;}
.live .demo-tag{color:var(--amber);font-weight:700;}
.nav{display:flex;gap:.3rem;padding:.25rem;background:var(--panel-solid);border:1px solid var(--line);border-radius:.9rem;transition:opacity .5s;}
.nav button{
  background:none;border:none;color:var(--mid);font:600 .95rem var(--sans);padding:.45rem 1.1rem;border-radius:.65rem;cursor:pointer;
}
.nav button:hover{color:var(--text);}
.nav button.active{background:var(--raised);color:var(--cyan);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--cyan) 40%,transparent);}
.nav .icon-btn{padding:.45rem .7rem;display:grid;place-items:center;}
.nav .icon-btn svg{width:1.1rem;height:1.1rem;}
body.idle.view-display .nav{opacity:0;pointer-events:none;}

/* ---------- Manage ---------- */
.toolbar{display:flex;align-items:center;gap:1rem;margin-bottom:1rem;}
.toolbar h2{font-size:1.4rem;font-weight:800;}
.toolbar .spacer{flex:1;}
.btn{
  background:linear-gradient(180deg,var(--btn-a),var(--btn-b));color:var(--btn-text);border:none;border-radius:.7rem;
  padding:.6rem 1.2rem;font:700 1rem var(--sans);cursor:pointer;
}
.btn:hover{filter:brightness(1.1);}
.btn.ghost{background:var(--raised);color:var(--text);border:1px solid var(--line-strong);}
.btn.danger{background:color-mix(in srgb,var(--red) 14%,transparent);color:var(--red);border:1px solid color-mix(in srgb,var(--red) 40%,transparent);}
.btn.small{padding:.4rem .75rem;font-size:.9rem;}

#manual-form{background:var(--panel);border:1px solid var(--line-strong);border-radius:1rem;padding:1.2rem;margin-bottom:1rem;backdrop-filter:blur(10px);}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(11rem,1fr));gap:.8rem;margin-bottom:1rem;}
label{display:block;font-size:.85rem;color:var(--mid);font-weight:600;margin-bottom:.3rem;}
input,select,textarea{
  width:100%;padding:.5rem .65rem;border:1px solid var(--line-strong);border-radius:.55rem;
  background:var(--input-bg);color:var(--text);font:500 .95rem var(--sans);
}
input:focus,select:focus,textarea:focus{outline:2px solid var(--cyan);outline-offset:1px;}
textarea{min-height:3rem;resize:vertical;}
::placeholder{color:var(--low);}

.table-card{background:var(--panel);border:1px solid var(--line);border-radius:1rem;overflow-x:auto;}
table{width:100%;border-collapse:collapse;}
.th-sort{all:unset;box-sizing:border-box;cursor:pointer;display:inline-flex;align-items:center;gap:.35rem;font:700 .85rem var(--sans);color:var(--mid);white-space:nowrap;padding:.1rem .2rem;border-radius:.4rem;}
.th-sort:hover{color:var(--text);}
.th-sort:focus-visible{outline:2px solid var(--cyan);outline-offset:2px;}
.th-sort .arr{font-size:.7rem;opacity:.4;}
.th-sort.on{color:var(--cyan);}
.th-sort.on .arr{opacity:1;}
.notes-input{min-height:5.5rem;min-width:18rem;font-size:1rem;}
th,td{padding:.7rem .6rem;text-align:right;border-bottom:1px solid var(--line);vertical-align:top;}
tbody tr:hover{background:var(--hover);}
tbody tr:last-child td{border-bottom:none;}
th{background:var(--th-bg);font-size:.8rem;color:var(--mid);font-weight:700;white-space:nowrap;position:sticky;top:0;z-index:1;}
th input,th select{margin-top:.3rem;padding:.3rem .45rem;font-size:.8rem;}
.name-input{font-weight:800;font-size:1.05rem;}
.cell-sub{font-size:.8rem;color:var(--low);margin-top:.25rem;}
.num-input{width:4.6rem;text-align:center;font-family:var(--mono);}
.row-actions{display:flex;gap:.4rem;flex-direction:column;min-width:6rem;}
.empty-box{text-align:center;color:var(--mid);padding:3rem;background:var(--panel);border:1px dashed var(--line-strong);border-radius:1rem;font-size:1.1rem;}

/* ---------- Archive ---------- */
.toolbar .tcount{font-family:var(--mono);font-size:.95rem;color:var(--mid);background:var(--raised);border:1px solid var(--line-strong);border-radius:2rem;padding:.15rem .75rem;}
dialog#arch-edit{background:var(--panel-solid,#0c1528);color:var(--text);border:1px solid var(--line-strong);border-radius:1rem;padding:1.5rem;width:min(56rem,92vw);max-height:90vh;overflow:auto;margin:auto;}
dialog#arch-edit::backdrop{background:var(--backdrop);backdrop-filter:blur(4px);}
dialog#arch-edit h3{font-size:1.3rem;font-weight:800;margin-bottom:1rem;}
.dlg-actions{display:flex;gap:.6rem;margin-top:1rem;}
.arch-table td{vertical-align:middle;font-size:.95rem;}
.arch-table .a-name{font-weight:800;font-size:1.05rem;}
.arch-table .mono{font-family:var(--mono);}
.arch-table .dim{color:var(--low);}
.arch-table .num{text-align:center;font-family:var(--mono);font-weight:700;}
.arch-table .num.zero{color:var(--low);font-weight:500;}
.badge{display:inline-block;padding:.15rem .6rem;border-radius:2rem;font-size:.85rem;font-weight:700;background:var(--raised);border:1px solid var(--line-strong);white-space:nowrap;}
.badge.in{color:var(--cyan);border-color:color-mix(in srgb,var(--cyan) 45%,transparent);}
.badge.out{color:var(--amber);border-color:color-mix(in srgb,var(--amber) 45%,transparent);}
.theme-wrap{position:relative;}
.theme-pop{
  position:absolute;inset-inline-end:0;bottom:calc(100% + .6rem);min-width:15rem;white-space:nowrap;z-index:20;
  background:var(--panel-solid);border:1px solid var(--line-strong);border-radius:.9rem;padding:.4rem;
  box-shadow:0 .8rem 2.4rem rgba(0,0,0,.35);display:none;flex-direction:column;gap:.15rem;
}
.theme-pop.open{display:flex;}
.theme-opt{
  display:flex;align-items:center;gap:.7rem;width:100%;text-align:start;
  background:none;border:none;color:var(--text);font:600 .95rem var(--sans);padding:.5rem .7rem;border-radius:.6rem;cursor:pointer;
}
.theme-opt:hover{background:var(--hover);}
.theme-opt.active{background:var(--raised);box-shadow:inset 0 0 0 1px var(--line-strong);}
.theme-opt .sw{width:1.5rem;height:1.5rem;border-radius:50%;border:1px solid var(--line-strong);flex:none;position:relative;overflow:hidden;}
.theme-opt .sw::after{content:'';position:absolute;inset-block:0;inset-inline-end:0;width:50%;background:var(--sw2);}
.theme-opt .chk{margin-inline-start:auto;opacity:0;color:var(--cyan);}
.theme-opt.active .chk{opacity:1;}
.arch-table textarea{min-height:3.2rem;min-width:14rem;}

@media (max-width:1100px){
  html{font-size:14px;}
  body{overflow:auto;}
  .app{height:auto;min-height:100vh;}
  .header{grid-template-columns:1fr;}
  .kpis{max-width:none;}
  .lanes,.arch-cols{grid-template-columns:1fr;}
  .metrics{grid-template-columns:repeat(3,1fr);}
  .clock{text-align:start;}
}
@media (prefers-reduced-motion:reduce){
  *,*::before{animation:none!important;transition:none!important;}
}
</style>
</head>
<body class="view-display">
<div class="app">

  <header class="header">
    <div class="brand">
      <div class="brand-mark" aria-hidden="true">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v11"/><circle cx="12" cy="5" r="1.6"/><path d="M5 12a7 7 0 0 0 14 0"/><path d="M3 12h4M17 12h4"/><path d="M3 20c1.5 0 1.5-1 3-1s1.5 1 3 1 1.5-1 3-1 1.5 1 3 1 1.5-1 3-1 1.5 1 3 1"/></svg>
      </div>
      <div>
        <div class="eyebrow">רשות האוכלוסין וההגירה</div>
        <h1>מסך מבצעי · מעבר גבול ימי</h1>
      </div>
    </div>

    <div class="kpis" aria-label="סיכום נתונים">
      <div class="kpi k-ships"><div class="n" id="stat-ships">0</div><div class="l">אוניות במסך</div></div>
      <div class="kpi k-crew"><div class="n" id="stat-crew">0</div><div class="l">אנשי צוות</div></div>
      <div class="kpi k-pax"><div class="n" id="stat-pax">0</div><div class="l">נוסעים</div></div>
      <div class="kpi k-treat" id="kpi-treat"><div class="n" id="stat-treat">0</div><div class="l">דורשי טיפול</div></div>
    </div>

    <div class="clock">
      <div class="time" id="clock">--:--<span>:--</span></div>
      <div class="date" id="date">--</div>
    </div>
  </header>

  <!-- Display view (TV) -->
  <main id="view-display" class="view active">
    <div class="lanes">
      <section class="lane in" aria-labelledby="h-in">
        <div class="lane-head">
          <div class="ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 4v14M6 12l6 6 6-6"/></svg></div>
          <h2 id="h-in">כניסות</h2>
          <div class="count" id="count-in">0</div>
        </div>
        <div class="lane-body" id="lane-in"></div>
      </section>
      <section class="lane out" aria-labelledby="h-out">
        <div class="lane-head">
          <div class="ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20V6M6 12l6-6 6 6"/></svg></div>
          <h2 id="h-out">יציאות</h2>
          <div class="count" id="count-out">0</div>
        </div>
        <div class="lane-body" id="lane-out"></div>
      </section>
    </div>
  </main>

  <!-- Manage view -->
  <section id="view-manage" class="view view-scroll">
    <div class="toolbar">
      <h2>ניהול אוניות</h2>
      <div class="spacer"></div>
      <button class="btn" onclick="showManual()">+ הוסף אוניה</button>
    </div>

    <div id="manual-form" style="display:none;">
      <div class="grid">
        <div><label for="m-name">שם אוניה *</label><input id="m-name"></div>
        <div><label for="m-agent">סוכן</label><input id="m-agent"></div>
        <div><label for="m-source">מקור הגעה</label>
          <select id="m-source"><option>חו"ל</option><option>חיפה</option><option>חדרה</option><option>אשקלון</option></select>
        </div>
        <div><label for="m-eta">זמן משוער</label><input type="datetime-local" id="m-eta"></div>
        <div><label for="m-berth">רציף</label><input id="m-berth"></div>
        <div><label for="m-dir">כיוון</label>
          <select id="m-dir"><option value="in">כניסה</option><option value="out">יציאה</option></select>
        </div>
        <div><label for="m-flag">דגל</label><input id="m-flag"></div>
        <div><label for="m-imo">IMO</label><input id="m-imo"></div>
      </div>
      <div style="display:flex;gap:.6rem;">
        <button class="btn" onclick="addManual()">הוסף</button>
        <button class="btn ghost" onclick="hideManual()">ביטול</button>
      </div>
    </div>

    <div id="table-wrap"></div>
    <div id="empty" class="empty-box" style="display:none;">אין אוניות. לחץ &quot;הוסף אוניה&quot; כדי להתחיל.</div>
  </section>

  <!-- Archive view -->
  <section id="view-archive" class="view view-scroll">
    <div class="toolbar">
      <h2>ארכיון</h2>
      <span class="tcount" id="arch-count">0</span>
    </div>
    <div id="arch-wrap"></div>
  </section>

  <footer class="footer">
    <div class="live" id="live"><i></i><span id="live-text">מתחבר…</span></div>
    <nav class="nav" aria-label="ניווט">
      <button data-view="display" class="active" onclick="switchView('display')">תצוגה</button>
      <button data-view="manage" onclick="switchView('manage')">ניהול</button>
      <button data-view="archive" onclick="switchView('archive')">ארכיון</button>
      <div class="theme-wrap">
        <button class="icon-btn" id="theme-btn" onclick="toggleThemeMenu(event)" title="פלטת צבעים (T)" aria-label="פלטת צבעים" aria-haspopup="true" aria-expanded="false">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3a9 9 0 1 0 0 18c1.1 0 1.8-.8 1.8-1.7 0-.5-.2-.9-.5-1.2-.3-.3-.5-.7-.5-1.2 0-.9.8-1.7 1.7-1.7H16a5 5 0 0 0 5-5c0-4-4-7.2-9-7.2z"/><circle cx="7.5" cy="11" r="1"/><circle cx="10.5" cy="7" r="1"/><circle cx="15.5" cy="7.5" r="1"/></svg>
        </button>
        <div class="theme-pop" id="theme-pop" role="menu" aria-label="בחירת פלטת צבעים">
          <button class="theme-opt" role="menuitemradio" data-theme-opt="dark" onclick="setTheme('dark')" style="--sw2:#22d3ee"><span class="sw" style="background:#0a1120"></span>כהה (חדר בקרה)<svg class="chk" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg></button>
          <button class="theme-opt" role="menuitemradio" data-theme-opt="light" onclick="setTheme('light')" style="--sw2:#0e7490"><span class="sw" style="background:#eef2f9"></span>בהיר<svg class="chk" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg></button>
          <button class="theme-opt" role="menuitemradio" data-theme-opt="sand" onclick="setTheme('sand')" style="--sw2:#0f766e"><span class="sw" style="background:#f6f1e7"></span>בהיר חם<svg class="chk" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg></button>
        </div>
      </div>
      <button class="icon-btn" onclick="toggleFullscreen()" title="מסך מלא (F)" aria-label="מסך מלא">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5"/></svg>
      </button>
    </nav>
  </footer>
</div>

<dialog id="arch-edit" aria-labelledby="arch-edit-title">
  <form method="dialog" onsubmit="event.preventDefault();saveArchEdit()">
    <h3 id="arch-edit-title">עריכת רשומה בארכיון</h3>
    <div class="grid">
      <div><label for="ae-name">שם אוניה *</label><input id="ae-name" required></div>
      <div><label for="ae-agent">סוכן</label><input id="ae-agent"></div>
      <div><label for="ae-source">מקור</label><select id="ae-source"></select></div>
      <div><label for="ae-dir">כיוון</label><select id="ae-dir"><option value="in">כניסה</option><option value="out">יציאה</option></select></div>
      <div><label for="ae-eta">זמן משוער</label><input type="datetime-local" id="ae-eta"></div>
      <div><label for="ae-berth">רציף</label><input id="ae-berth"></div>
      <div><label for="ae-flag">דגל</label><input id="ae-flag"></div>
      <div><label for="ae-imo">IMO</label><input id="ae-imo"></div>
      <div><label for="ae-crew">צוות</label><input type="number" min="0" id="ae-crew"></div>
      <div><label for="ae-pax">נוסעים</label><input type="number" min="0" id="ae-pax"></div>
      <div><label for="ae-treat">טיפול</label><input type="number" min="0" id="ae-treat"></div>
      <div><label for="ae-status">סטטוס</label><select id="ae-status"></select></div>
      <div><label for="ae-archivedAt">הועבר לארכיון</label><input type="datetime-local" id="ae-archivedAt"></div>
    </div>
    <label for="ae-notes">הערות</label>
    <textarea id="ae-notes" class="notes-input" style="min-width:0;width:100%;"></textarea>
    <div class="dlg-actions">
      <button type="submit" class="btn">שמור</button>
      <button type="button" class="btn ghost" onclick="closeArchEdit()">ביטול</button>
    </div>
  </form>
</dialog>

<script>
const REFRESH_MS = 10000;
const DEMO_KEY = 'ashdod_board_demo_v2';
const STATUS_IN = ['עוגן מחוץ לנמל','מוכן לביקורת','אחרי ביקורת','בטיפול'];
const STATUS_OUT = ['תהליך בדיקת יציאה','אוניה שוחררה'];
const STATUS_CLASS = {
  'עוגן מחוץ לנמל':'s-wait',
  'מוכן לביקורת':'s-ready',
  'אחרי ביקורת':'s-ok',
  'בטיפול':'s-active',
  'תהליך בדיקת יציאה':'s-ready',
  'אוניה שוחררה':'s-ok'
};

let ships = [];
let archive = [];
let demo = false;
let view = 'display';
let lastUpdate = null;
let loadFailed = false;

function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
const pad = n => String(n).padStart(2,'0');
const num = v => (v===null||v===undefined||v==='') ? null : Number(v);

/* ---------- Data ---------- */
function seedDemo(){
  const at = h => { const d=new Date(Date.now()+h*3600e3); return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`; };
  const base = {notes:'',crew:null,pax:null,treat:null};
  return {
    main:[
      {...base,id:1,name:'MSC Aurora',agent:'ג׳נרל שיפינג',source:'חו"ל',eta:at(1.5),berth:'12',direction:'in',flag:'פנמה',imo:'9839430',crew:24,pax:1480,treat:3,status:'מוכן לביקורת',notes:'נדרש צוות רפואי בעגינה'},
      {...base,id:2,name:'Costa Smeralda',agent:'מרין אקספרס',source:'חיפה',eta:at(-0.4),berth:'7',direction:'in',flag:'איטליה',imo:'9781865',crew:18,pax:920,treat:0,status:'בטיפול'},
      {...base,id:3,name:'Aegean Spirit',agent:'ים תיכון סוכנויות',source:'חו"ל',eta:at(5),berth:'',direction:'in',flag:'יוון',imo:'9456123',crew:16,pax:0,treat:0,status:'עוגן מחוץ לנמל'},
      {...base,id:4,name:'Blue Horizon',agent:'אורבן ים',source:'אשקלון',eta:at(2.2),berth:'4',direction:'in',flag:'קפריסין',imo:'9702221',crew:12,pax:210,treat:1,status:'אחרי ביקורת'},
      {...base,id:5,name:'Mediterranean Pearl',agent:'ג׳נרל שיפינג',source:'חדרה',eta:at(-1.2),berth:'9',direction:'in',flag:'מלטה',imo:'9610458',crew:20,pax:640,treat:0,status:'מוכן לביקורת'},
      {...base,id:6,name:'Nordic Star',agent:'מרין אקספרס',source:'חו"ל',eta:'',berth:'3',direction:'out',flag:'נורווגיה',imo:'9533012',crew:22,pax:310,treat:0,status:'תהליך בדיקת יציאה'},
      {...base,id:7,name:'Sea Voyager',agent:'אורבן ים',source:'חיפה',eta:'',berth:'6',direction:'out',flag:'ליבריה',imo:'9487750',crew:15,pax:0,treat:0,status:'תהליך בדיקת יציאה',notes:'ממתין לאישור סוכן'}
    ],
    archive:[]
  };
}

async function fetchData(){
  try{
    const r = await fetch('/ships',{cache:'no-store'});
    if(!r.ok) throw new Error('http '+r.status);
    const d = await r.json();
    ships = d.main||[]; archive = d.archive||[];
    demo = false; loadFailed = false;
  }catch(e){
    demo = true;
    let d = null;
    try{ d = JSON.parse(localStorage.getItem(DEMO_KEY)||'null'); }catch(_){}
    if(!d){ d = seedDemo(); localStorage.setItem(DEMO_KEY, JSON.stringify(d)); }
    ships = d.main||[]; archive = d.archive||[];
  }
  lastUpdate = new Date();
  setLive();
}

async function save(){
  if(demo){
    try{ localStorage.setItem(DEMO_KEY, JSON.stringify({main:ships,archive})); }catch(_){}
    return;
  }
  try{
    await fetch('/ships',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({main:ships,archive})});
    loadFailed = false;
  }catch(e){ loadFailed = true; }
  setLive();
}

function setLive(){
  const el = document.getElementById('live');
  const t = document.getElementById('live-text');
  el.className = 'live' + (demo ? ' demo' : '') + (loadFailed ? ' err' : '');
  const time = lastUpdate ? lastUpdate.toLocaleTimeString('he-IL') : '';
  t.innerHTML = loadFailed
    ? 'שגיאת שמירה — בדוק חיבור לשרת'
    : (demo ? '<span class="demo-tag">מצב הדגמה</span> · נתונים מקומיים' : `מתעדכן אוטומטית כל ${REFRESH_MS/1000} שניות · עודכן ${time}`);
}

/* ---------- Stats ---------- */
function updateStats(){
  const sum = k => ships.reduce((a,s)=>a+(+s[k]||0),0);
  const treat = sum('treat');
  document.getElementById('stat-ships').textContent = ships.length;
  document.getElementById('stat-crew').textContent = sum('crew').toLocaleString('he-IL');
  document.getElementById('stat-pax').textContent = sum('pax').toLocaleString('he-IL');
  document.getElementById('stat-treat').textContent = treat;
  document.getElementById('kpi-treat').classList.toggle('hot', treat>0);
}

/* ---------- Display ---------- */
function etaInfo(iso){
  if(!iso) return {time:'—',sub:'',cls:''};
  const d = new Date(iso);
  if(isNaN(d)) return {time:esc(iso),sub:'',cls:''};
  const now = new Date();
  const time = `${pad(d.getHours())}:${pad(d.getMinutes())}`;
  const sameDay = d.toDateString()===now.toDateString();
  const dateStr = sameDay ? '' : `${pad(d.getDate())}/${pad(d.getMonth()+1)} `;
  const diff = Math.round((d-now)/60000);
  const abs = Math.abs(diff);
  let rel;
  if(abs>=2880) rel = `${Math.floor(abs/1440)} ימים`;
  else rel = `${Math.floor(abs/60)}:${pad(abs%60)} ש׳`;
  if(diff>=0) return {time:dateStr+time, sub:'בעוד '+rel, cls: diff<30?'soon':''};
  return {time:dateStr+time, sub:'באיחור '+rel, cls:'late'};
}

/* ---------- Long-wait alert ---------- */
const WAIT_ALERT_DAYS = 15;
const WAIT_ALERT_LABEL = `ממתין מעל ${WAIT_ALERT_DAYS} יום`;

function sameShip(a,b){
  if(a.imo && b.imo) return String(a.imo).trim()===String(b.imo).trim();
  return (a.name||'').trim().toLowerCase()===(b.name||'').trim().toLowerCase();
}
/* The docking estimate the wait is measured from. An exit uses the estimate of the entry it came from. */
function waitRefTime(s){
  if(s.direction!=='out') return s.eta;
  if(s.entryEta) return s.entryEta;
  if(s.eta) return s.eta;
  const past = archive
    .filter(a=>a.direction!=='out' && a.eta && sameShip(a,s))
    .sort((x,y)=>new Date(y.archivedAt||0)-new Date(x.archivedAt||0));
  return past.length ? past[0].eta : '';
}
function waitDays(s){
  const ref = waitRefTime(s);
  if(!ref) return null;
  const t = new Date(ref).getTime();
  if(isNaN(t)) return null;
  return Math.floor((Date.now()-t)/86400000);
}
function isLongWait(s){
  const d = waitDays(s);
  return d!==null && d>=WAIT_ALERT_DAYS;
}

function metric(k,v,opts={}){
  const zero = (v===null||v===undefined||v===''||v===0);
  const shown = (v===null||v===undefined||v==='') ? '—' : v;
  return `<div class="m ${opts.cls||''}"><span class="k">${k}</span><span class="v ${opts.mono?'mono':''} ${zero&&opts.dimZero?'zero':''}">${esc(shown)}</span></div>`;
}

function card(s){
  const e = etaInfo(s.eta);
  const cls = STATUS_CLASS[s.status] || 's-wait';
  const treat = +s.treat||0;
  const long = isLongWait(s);
  return `
  <article class="card ${cls} ${treat>0?'has-treat':''} ${long?'long-wait':''}">
    <div class="card-top">
      <div style="min-width:0;">
        <h3 class="ship-name">${esc(s.name)}</h3>
        <div class="ship-meta">
          ${s.flag?`<b>${esc(s.flag)}</b><span class="sep">·</span>`:''}${s.imo?`IMO ${esc(s.imo)}<span class="sep">·</span>`:''}סוכן: <b>${esc(s.agent||'—')}</b>
        </div>
      </div>
      <div class="pills">
        ${long?`<span class="pill alert"><i></i>${WAIT_ALERT_LABEL}</span>`:''}
        <span class="pill"><i></i>${esc(s.status)}</span>
      </div>
    </div>
    <div class="metrics">
      <div class="m"><span class="k">${s.direction==='out'?'יציאה':'זמן משוער'}</span><span class="v mono">${e.time}</span>${e.sub?`<span class="sub ${e.cls}">${e.sub}</span>`:''}</div>
      ${metric('מקור',s.source)}
      ${metric('רציף',s.berth,{mono:true})}
      ${metric('צוות',s.crew,{mono:true,dimZero:true})}
      ${metric('נוסעים',s.pax,{mono:true,dimZero:true})}
      ${metric('טיפול',s.treat,{mono:true,dimZero:true,cls:'treat'})}
    </div>
    ${s.notes?`<div class="card-notes">${esc(s.notes)}</div>`:''}
  </article>`;
}

function sortByEta(a,b){
  const ta = a.eta ? new Date(a.eta).getTime() : Infinity;
  const tb = b.eta ? new Date(b.eta).getTime() : Infinity;
  return (isNaN(ta)?Infinity:ta) - (isNaN(tb)?Infinity:tb);
}

const laneCache = {};
function fillLane(id, list, emptyText){
  const el = document.getElementById(id);
  const html = list.length ? list.map(card).join('') : `<div class="lane-empty">${emptyText}</div>`;
  if(laneCache[id] !== html){
    const top = el.scrollTop;
    el.innerHTML = html;
    el.scrollTop = top;
    laneCache[id] = html;
  }
}

function renderDisplay(){
  const ins = ships.filter(s=>s.direction!=='out').sort(sortByEta);
  const outs = ships.filter(s=>s.direction==='out').sort(sortByEta);
  document.getElementById('count-in').textContent = ins.length;
  document.getElementById('count-out').textContent = outs.length;
  fillLane('lane-in', ins, 'אין כניסות צפויות');
  fillLane('lane-out', outs, 'אין יציאות בתהליך');
}

/* Slow auto-scroll for lanes that overflow the screen */
const scrollState = new WeakMap();
let lastFrame = performance.now();
function autoScroll(now){
  const dt = Math.min(now-lastFrame, 100);
  lastFrame = now;
  if(view==='display'){
    document.querySelectorAll('.lane-body').forEach(el=>{
      const max = el.scrollHeight - el.clientHeight;
      const over = max > 4;
      el.classList.toggle('overflowing', over);
      let st = scrollState.get(el);
      if(!st){ st = {phase:'top',wait:0,pos:0}; scrollState.set(el,st); }
      if(!over){ el.scrollTop = 0; st.phase='top'; st.wait=0; st.pos=0; return; }
      if(st.phase==='top'){ st.wait += dt; if(st.wait>6000){ st.phase='down'; st.wait=0; } }
      else if(st.phase==='down'){
        st.pos += dt*0.035*(parseFloat(getComputedStyle(document.documentElement).fontSize)/16);
        if(st.pos>=max){ st.pos=max; st.phase='bottom'; st.wait=0; }
        el.scrollTop = st.pos;
      } else if(st.phase==='bottom'){
        st.wait += dt;
        if(st.wait>5000){ st.pos=0; el.scrollTop=0; st.phase='top'; st.wait=0; }
      }
    });
  }
  requestAnimationFrame(autoScroll);
}

/* ---------- Manage ---------- */
function showManual(){document.getElementById('manual-form').style.display='block';document.getElementById('m-name').focus();}
function hideManual(){document.getElementById('manual-form').style.display='none';}

function addManual(){
  const name = document.getElementById('m-name').value.trim();
  if(!name){alert('יש להזין שם');return;}
  const dir = document.getElementById('m-dir').value;
  ships.push({
    id:Date.now(), name,
    agent:document.getElementById('m-agent').value.trim(),
    source:document.getElementById('m-source').value,
    eta:document.getElementById('m-eta').value,
    berth:document.getElementById('m-berth').value.trim(),
    direction:dir,
    flag:document.getElementById('m-flag').value.trim(),
    imo:document.getElementById('m-imo').value.trim(),
    crew:null,pax:null,treat:null,notes:'',
    status: dir==='out' ? 'תהליך בדיקת יציאה' : 'מוכן לביקורת'
  });
  save(); hideManual();
  ['m-name','m-agent','m-eta','m-berth','m-flag','m-imo'].forEach(id=>document.getElementById(id).value='');
  renderAll();
}

function getFilters(){
  const v = id => (document.getElementById(id)||{}).value||'';
  return {name:v('f-name'),agent:v('f-agent'),source:v('f-source'),dir:v('f-dir'),status:v('f-status')};
}
function filtered(){
  const f = getFilters();
  return ships.filter(s=>{
    if(f.name && !(s.name||'').toLowerCase().includes(f.name.toLowerCase())) return false;
    if(f.agent && !(s.agent||'').toLowerCase().includes(f.agent.toLowerCase())) return false;
    if(f.source && s.source!==f.source) return false;
    if(f.dir && s.direction!==f.dir) return false;
    if(f.status && s.status!==f.status) return false;
    return true;
  });
}
function statusOpts(s){
  const list = s.direction==='out' ? STATUS_OUT : STATUS_IN;
  return list.map(x=>`<option ${s.status===x?'selected':''}>${x}</option>`).join('');
}
const SOURCES = ['חו"ל','חיפה','חדרה','אשקלון'];

const sortState = {manage:{key:null,dir:1}, archive:{key:'archivedAt',dir:-1}};
const TIME_KEYS = ['eta','archivedAt'], NUM_KEYS = ['crew','pax','treat'];
function sortVal(s,key){
  if(TIME_KEYS.includes(key)){ const t = s[key] ? new Date(s[key]).getTime() : NaN; return isNaN(t) ? null : t; }
  if(NUM_KEYS.includes(key)) return (s[key]===null||s[key]===undefined||s[key]==='') ? null : +s[key];
  const v = (s[key]||'').toString().trim().toLowerCase();
  return v==='' ? null : v;
}
function sortList(list,scope){
  const {key,dir} = sortState[scope];
  if(!key) return list;
  return list.slice().sort((a,b)=>{
    const x = sortVal(a,key), y = sortVal(b,key);
    if(x===null && y===null) return 0;
    if(x===null) return 1;
    if(y===null) return -1;
    const c = typeof x==='number' ? x-y : x.localeCompare(y,'he',{numeric:true});
    return c*dir;
  });
}
function sortTh(scope,key,label,extra=''){
  const st = sortState[scope], on = st.key===key;
  const arrow = on ? (st.dir===1?'▲':'▼') : '↕';
  const aria = on ? (st.dir===1?'ascending':'descending') : 'none';
  return `<th aria-sort="${aria}"><button type="button" class="th-sort ${on?'on':''}" onclick="setSort('${scope}','${key}')">${label}<span class="arr" aria-hidden="true">${arrow}</span></button>${extra}</th>`;
}
function setSort(scope,key){
  const st = sortState[scope];
  if(st.key!==key){ st.key=key; st.dir=1; }
  else if(st.dir===1) st.dir=-1;
  else { st.key = scope==='archive' ? 'archivedAt' : null; st.dir = scope==='archive' ? -1 : 1; }
  if(scope==='manage') renderManage(); else renderArchive();
}

function renderManage(){
  const wrap = document.getElementById('table-wrap');
  const empty = document.getElementById('empty');
  if(!ships.length){wrap.innerHTML='';empty.style.display='block';return;}
  empty.style.display='none';
  const f = getFilters();
  const list = sortList(filtered(),'manage');
  wrap.innerHTML = `
  <div class="table-card"><table>
    <thead><tr>
      ${sortTh('manage','name','שם',`<br><input id="f-name" placeholder="סינון" oninput="renderManage();refocus('f-name')">`)}
      ${sortTh('manage','agent','סוכן',`<br><input id="f-agent" placeholder="סינון" oninput="renderManage();refocus('f-agent')">`)}
      ${sortTh('manage','source','מקור',`<br><select id="f-source" onchange="renderManage()"><option value="">הכל</option>${SOURCES.map(x=>`<option>${esc(x)}</option>`).join('')}</select>`)}
      ${sortTh('manage','eta','זמן משוער')}
      ${sortTh('manage','berth','רציף')}
      ${sortTh('manage','direction','כיוון',`<br><select id="f-dir" onchange="renderManage()"><option value="">הכל</option><option value="in">כניסה</option><option value="out">יציאה</option></select>`)}
      ${sortTh('manage','crew','צוות')}
      ${sortTh('manage','pax','נוסעים')}
      ${sortTh('manage','treat','טיפול')}
      ${sortTh('manage','status','סטטוס',`<br><select id="f-status" onchange="renderManage()"><option value="">הכל</option>${[...STATUS_IN,...STATUS_OUT].map(x=>`<option>${x}</option>`).join('')}</select>`)}
      ${sortTh('manage','notes','הערות')}
      <th></th>
    </tr></thead>
    <tbody>
    ${list.map(s=>`
      <tr class="${isLongWait(s)?'row-long-wait':''}">
        <td><input class="name-input" value="${esc(s.name)}" onchange="upd(${s.id},'name',this.value)"><div class="cell-sub">${esc(s.flag||'')} ${s.imo?'· '+esc(s.imo):''}</div></td>
        <td><input value="${esc(s.agent||'')}" onchange="upd(${s.id},'agent',this.value)"></td>
        <td><select onchange="upd(${s.id},'source',this.value)">${SOURCES.map(x=>`<option ${s.source===x?'selected':''}>${esc(x)}</option>`).join('')}</select></td>
        <td><input type="datetime-local" value="${esc(s.eta||'')}" onchange="upd(${s.id},'eta',this.value)"></td>
        <td><input value="${esc(s.berth||'')}" onchange="upd(${s.id},'berth',this.value)" style="width:4.5rem;"></td>
        <td><select onchange="changeDir(${s.id},this.value)"><option value="in" ${s.direction!=='out'?'selected':''}>כניסה</option><option value="out" ${s.direction==='out'?'selected':''}>יציאה</option></select></td>
        <td><input class="num-input" type="number" min="0" aria-label="צוות" value="${s.crew??''}" onchange="upd(${s.id},'crew',this.value)"></td>
        <td><input class="num-input" type="number" min="0" aria-label="נוסעים" value="${s.pax??''}" onchange="upd(${s.id},'pax',this.value)"></td>
        <td><input class="num-input" type="number" min="0" aria-label="דורשי טיפול" value="${s.treat??''}" onchange="upd(${s.id},'treat',this.value)"></td>
        <td><select onchange="changeStatus(${s.id},this.value)">${statusOpts(s)}</select>${isLongWait(s)?`<br><span class="wait-badge"><i></i>${WAIT_ALERT_LABEL}</span>`:''}</td>
        <td><textarea class="notes-input" aria-label="הערות" onchange="upd(${s.id},'notes',this.value)">${esc(s.notes||'')}</textarea></td>
        <td class="row-actions">
          ${s.direction==='out' ? '' : `<button class="btn small" onclick="createExit(${s.id})">צור יציאה</button>`}
          <button class="btn danger small" onclick="removeShip(${s.id})">הסר</button>
        </td>
      </tr>`).join('')}
    </tbody>
  </table></div>`;
  ['name','agent','source','dir','status'].forEach(k=>{
    const el = document.getElementById('f-'+k); if(el) el.value = f[k];
  });
}
function refocus(id){const el=document.getElementById(id);if(el){el.focus();const l=el.value.length;el.setSelectionRange(l,l);}}

function upd(id,field,val){
  const s = ships.find(x=>x.id===id); if(!s) return;
  if(['crew','pax','treat'].includes(field)) val = num(val);
  s[field] = val; save(); updateStats();
}
function changeDir(id,dir){
  const s = ships.find(x=>x.id===id); if(!s) return;
  if(dir==='out' && s.direction!=='out' && s.eta && !s.entryEta) s.entryEta = s.eta;
  s.direction = dir;
  if(dir==='out' && !STATUS_OUT.includes(s.status)) s.status = 'תהליך בדיקת יציאה';
  if(dir==='in' && !STATUS_IN.includes(s.status)) s.status = 'מוכן לביקורת';
  save(); renderAll();
}
function changeStatus(id,status){
  const s = ships.find(x=>x.id===id); if(!s) return;
  if(status==='אוניה שוחררה'){
    archive.push({...s,status,archivedAt:new Date().toISOString()});
    ships = ships.filter(x=>x.id!==id);
  } else s.status = status;
  save(); renderAll();
}
function createExit(id){
  const s = ships.find(x=>x.id===id); if(!s) return;
  archive.push({...s,archivedAt:new Date().toISOString()});
  const clone = {...s,id:Date.now(),direction:'out',status:'תהליך בדיקת יציאה',eta:'',entryEta:s.entryEta||s.eta||'',notes:''};
  ships = ships.filter(x=>x.id!==id);
  ships.push(clone);
  save(); renderAll();
}
function removeShip(id){
  if(!confirm('להסיר את האוניה?')) return;
  ships = ships.filter(s=>s.id!==id); save(); renderAll();
}

/* ---------- Archive ---------- */
function fmtEta(iso){
  if(!iso) return '—';
  const d = new Date(iso);
  return isNaN(d) ? iso : d.toLocaleString('he-IL',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
}
function getArchFilters(){
  const v = id => (document.getElementById(id)||{}).value||'';
  return {name:v('fa-name'),agent:v('fa-agent'),source:v('fa-source'),dir:v('fa-dir')};
}
function renderArchive(){
  const wrap = document.getElementById('arch-wrap');
  const counter = document.getElementById('arch-count');
  if(!archive.length){
    wrap.innerHTML = '<div class="empty-box">הארכיון ריק.</div>';
    counter.textContent = '0';
    return;
  }
  const f = getArchFilters();
  const list = sortList(archive.filter(s=>{
    if(f.name && !(s.name||'').toLowerCase().includes(f.name.toLowerCase())) return false;
    if(f.agent && !(s.agent||'').toLowerCase().includes(f.agent.toLowerCase())) return false;
    if(f.source && s.source!==f.source) return false;
    if(f.dir && (s.direction==='out'?'out':'in')!==f.dir) return false;
    return true;
  }),'archive');
  counter.textContent = list.length===archive.length ? archive.length : `${list.length} / ${archive.length}`;
  const numCell = v => `<td class="num ${(!v)?'zero':''}">${(v===null||v===undefined||v==='')?'—':esc(v)}</td>`;
  wrap.innerHTML = `
  <div class="table-card"><table class="arch-table">
    <thead><tr>
      ${sortTh('archive','name','שם',`<br><input id="fa-name" placeholder="סינון" oninput="renderArchive();refocus('fa-name')">`)}
      ${sortTh('archive','agent','סוכן',`<br><input id="fa-agent" placeholder="סינון" oninput="renderArchive();refocus('fa-agent')">`)}
      ${sortTh('archive','source','מקור',`<br><select id="fa-source" onchange="renderArchive()"><option value="">הכל</option>${SOURCES.map(x=>`<option>${esc(x)}</option>`).join('')}</select>`)}
      ${sortTh('archive','direction','כיוון',`<br><select id="fa-dir" onchange="renderArchive()"><option value="">הכל</option><option value="in">כניסה</option><option value="out">יציאה</option></select>`)}
      ${sortTh('archive','eta','זמן משוער')}
      ${sortTh('archive','berth','רציף')}
      ${sortTh('archive','crew','צוות')}
      ${sortTh('archive','pax','נוסעים')}
      ${sortTh('archive','treat','טיפול')}
      ${sortTh('archive','status','סטטוס')}
      ${sortTh('archive','archivedAt','הועבר לארכיון')}
      ${sortTh('archive','notes','הערות')}
      <th></th>
    </tr></thead>
    <tbody>
    ${list.length ? list.map(s=>`
      <tr>
        <td><div class="a-name">${esc(s.name)}</div><div class="cell-sub">${esc(s.flag||'')} ${s.imo?'· '+esc(s.imo):''}</div></td>
        <td>${esc(s.agent||'—')}</td>
        <td>${esc(s.source||'—')}</td>
        <td><span class="badge ${s.direction==='out'?'out':'in'}">${s.direction==='out'?'יציאה':'כניסה'}</span></td>
        <td class="mono">${esc(fmtEta(s.eta))}</td>
        <td class="mono">${esc(s.berth||'—')}</td>
        ${numCell(s.crew)}${numCell(s.pax)}${numCell(s.treat)}
        <td><span class="badge">${esc(s.status||'—')}</span></td>
        <td class="mono dim">${s.archivedAt?esc(new Date(s.archivedAt).toLocaleString('he-IL',{day:'2-digit',month:'2-digit',year:'2-digit',hour:'2-digit',minute:'2-digit'})):'—'}</td>
        <td><textarea class="notes-input" aria-label="הערות" onchange="editArch(${s.id},this.value)">${esc(s.notes||'')}</textarea></td>
        <td class="row-actions"><button class="btn small" onclick="openArchEdit(${s.id})">ערוך</button></td>
      </tr>`).join('') : '<tr><td colspan="13" style="text-align:center;color:var(--mid);padding:2rem;">אין תוצאות</td></tr>'}
    </tbody>
  </table></div>`;
  [['name','fa-name'],['agent','fa-agent'],['source','fa-source'],['dir','fa-dir']].forEach(([k,id])=>{
    const el = document.getElementById(id); if(el) el.value = f[k];
  });
}
function editArch(id,notes){const s=archive.find(x=>x.id===id);if(s){s.notes=notes;save();}}

const toLocalInput = iso => {
  if(!iso) return '';
  const d = new Date(iso);
  if(isNaN(d)) return '';
  return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
};
let editingArchId = null;
function openArchEdit(id){
  const s = archive.find(x=>x.id===id); if(!s) return;
  editingArchId = id;
  const set = (k,v) => document.getElementById('ae-'+k).value = v ?? '';
  document.getElementById('ae-source').innerHTML = SOURCES.map(x=>`<option>${esc(x)}</option>`).join('');
  document.getElementById('ae-status').innerHTML = [...STATUS_IN,...STATUS_OUT].map(x=>`<option>${x}</option>`).join('');
  set('name',s.name); set('agent',s.agent); set('source',s.source); set('eta',s.eta);
  set('berth',s.berth); set('dir',s.direction==='out'?'out':'in'); set('flag',s.flag); set('imo',s.imo);
  set('crew',s.crew); set('pax',s.pax); set('treat',s.treat); set('status',s.status);
  set('archivedAt',toLocalInput(s.archivedAt)); set('notes',s.notes);
  document.getElementById('arch-edit').showModal();
}
function closeArchEdit(){ document.getElementById('arch-edit').close(); editingArchId = null; }
function saveArchEdit(){
  const s = archive.find(x=>x.id===editingArchId); if(!s) return closeArchEdit();
  const v = k => document.getElementById('ae-'+k).value;
  const name = v('name').trim();
  if(!name){ alert('יש להזין שם'); return; }
  Object.assign(s,{
    name, agent:v('agent').trim(), source:v('source'), eta:v('eta'), berth:v('berth').trim(),
    direction:v('dir'), flag:v('flag').trim(), imo:v('imo').trim(),
    crew:num(v('crew')), pax:num(v('pax')), treat:num(v('treat')),
    status:v('status'), notes:v('notes')
  });
  const at = v('archivedAt');
  if(at) s.archivedAt = new Date(at).toISOString();
  save(); closeArchEdit(); renderAll();
}

/* ---------- Navigation ---------- */
function renderAll(){
  updateStats();
  if(view==='display') renderDisplay();
  else if(view==='manage') renderManage();
  else renderArchive();
}
function switchView(name){
  if(!['display','manage','archive'].includes(name)) name='display';
  view = name;
  document.querySelectorAll('.view').forEach(p=>p.classList.remove('active'));
  document.getElementById('view-'+name).classList.add('active');
  document.querySelectorAll('.nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));
  document.body.classList.remove('view-display','view-manage','view-archive');
  document.body.classList.add('view-'+name);
  if(location.hash.slice(1)!==name) history.replaceState(null,'','#'+name);
  document.body.style.overflow = (name==='display' && innerWidth>1100) ? 'hidden' : '';
  renderAll();
}
/* ---------- Theme ---------- */
const THEMES = {dark:'#060a14', light:'#eef2f9', sand:'#f6f1e7'};
function currentTheme(){ return document.documentElement.getAttribute('data-theme') || 'dark'; }
function setTheme(t){
  if(!THEMES[t]) t='dark';
  if(t==='dark') document.documentElement.removeAttribute('data-theme');
  else document.documentElement.setAttribute('data-theme',t);
  try{ localStorage.setItem('board-theme',t); }catch(_){}
  document.querySelector('meta[name="theme-color"]').content = THEMES[t];
  document.querySelector('meta[name="color-scheme"]').content = t==='dark' ? 'dark' : 'light';
  document.querySelectorAll('.theme-opt').forEach(b=>{
    const on = b.dataset.themeOpt===t;
    b.classList.toggle('active',on);
    b.setAttribute('aria-checked',on);
  });
  closeThemeMenu();
}
function toggleThemeMenu(e){
  if(e) e.stopPropagation();
  const pop = document.getElementById('theme-pop');
  const open = pop.classList.toggle('open');
  document.getElementById('theme-btn').setAttribute('aria-expanded',open);
}
function closeThemeMenu(){
  document.getElementById('theme-pop').classList.remove('open');
  document.getElementById('theme-btn').setAttribute('aria-expanded','false');
}
document.addEventListener('click',e=>{ if(!e.target.closest('.theme-wrap')) closeThemeMenu(); });
setTheme(currentTheme());

function toggleFullscreen(){
  if(document.fullscreenElement) document.exitFullscreen();
  else document.documentElement.requestFullscreen && document.documentElement.requestFullscreen();
}

/* Auto-hide controls and cursor on the TV after a few seconds of inactivity */
let idleTimer;
function wake(){
  document.body.classList.remove('idle');
  clearTimeout(idleTimer);
  idleTimer = setTimeout(()=>document.body.classList.add('idle'), 6000);
}
['mousemove','keydown','touchstart','click'].forEach(ev=>addEventListener(ev,wake,{passive:true}));
addEventListener('keydown',e=>{
  if(/INPUT|TEXTAREA|SELECT/.test((e.target||{}).tagName)) return;
  if(e.key==='f'||e.key==='F') toggleFullscreen();
  if(e.key==='t'||e.key==='T'||e.key==='א'){
    const order=['dark','light','sand'];
    setTheme(order[(order.indexOf(currentTheme())+1)%order.length]);
  }
  if(e.key==='Escape') closeThemeMenu();
  if(e.key==='1') switchView('display');
  if(e.key==='2') switchView('manage');
  if(e.key==='3') switchView('archive');
});
addEventListener('hashchange',()=>switchView(location.hash.slice(1)));

/* ---------- Clock ---------- */
function tick(){
  const now = new Date();
  document.getElementById('clock').innerHTML = `${pad(now.getHours())}:${pad(now.getMinutes())}<span>:${pad(now.getSeconds())}</span>`;
  document.getElementById('date').textContent = now.toLocaleDateString('he-IL',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
}
setInterval(tick,1000); tick();

/* ---------- Refresh loop ---------- */
function userIsEditing(){
  if(document.getElementById('manual-form').style.display==='block') return true;
  if(document.getElementById('arch-edit').open) return true;
  const a = document.activeElement;
  return !!a && /INPUT|TEXTAREA|SELECT/.test(a.tagName) && a.closest('#view-manage,#view-archive');
}
async function refresh(){
  if(!demo && userIsEditing()) return;
  await fetchData();
  renderAll();
}
setInterval(refresh, REFRESH_MS);
setInterval(()=>{ if(view==='display') renderDisplay(); }, 30000);

(async function init(){
  await fetchData();
  switchView(location.hash.slice(1) || 'display');
  wake();
  requestAnimationFrame(autoScroll);
})();
</script>
</body>
</html>
"""


